examples.template:
VStack(alignment: .leading, spacing: 8) {
    MonarchEntityPicker(
        {{label}},
        selection: $project,
        entities: [
            MonarchEntityPickerEntity(id: {{projects.0.value}}, name: {{projects.0.label}}, hint: {{projects.0.hint}}, systemImage: "rectangle.3.group", shape: .square, group: {{projects.0.group}}),
            MonarchEntityPickerEntity(id: {{projects.1.value}}, name: {{projects.1.label}}, hint: {{projects.1.hint}}, systemImage: "list.bullet", shape: .square, group: {{projects.1.group}}),
            MonarchEntityPickerEntity(id: {{projects.2.value}}, name: {{projects.2.label}}, hint: {{projects.2.hint}}, systemImage: "square.grid.2x2", shape: .square, group: {{projects.2.group}}),
            MonarchEntityPickerEntity(id: {{projects.3.value}}, name: {{projects.3.label}}, description: {{projects.3.description}}, hint: {{projects.3.hint}}, systemImage: "list.bullet", shape: .square, group: {{projects.3.group}}),
        ],
        prompt: {{placeholder}},
        clearOptionTitle: {{clearOption}},
        footerTitle: {{footer}}
    )
}

examples.setup:
@State private var reviewers: [String] = []

private nonisolated static let directory = [
    MonarchEntityPickerEntity(id: "ana", name: "Ana Silva"),
    MonarchEntityPickerEntity(id: "lin", name: "Lin Chen"),
]

examples.code:
MonarchEntityPicker(
    "Reviewers",
    selection: $reviewers,
    entities: [],
    prompt: "Add reviewers",
    minSearchLength: 2,
    search: { query in
        Self.directory.filter { $0.name.localizedStandardContains(query) }
    }
)
